    "use": "Gelatin is an animal-derived gelling agent and stabilizer used in jellies, desserts, confectionery and some capsules or processed foods.",
    "tox": "JECFA records “ADI not limited” for edible gelatin in a historical evaluation. This is not unlimited intake advice and does not remove the need to consider contaminants, formulation, food-category rules or a person’s medical circumstances.",
